(function(){const t=23,n=240,e=160;let l=0,i=0,o=0,r=0;const a=new Float32Array(t),f=new Float32Array(t);return{init:function(n){l=n,i=0,o=0,r=0;for(let n=0;n<t;n++)f[n]=-1},draw:function(h){"ram";const c=3+3*l;if(o>0)o--;else for(let n=0;n<t;n++)if(f[n]<0){f[n]=4,a[n]=Math.randInt(628)/100,r<1&&0===Math.randInt(2)?(o=Math.randInt(2),r++):(o=Math.randInt(3)+2,r=0);break}for(let l=0;l<t;l++){const t=f[l];if(t<0)continue;const o=Math.cos(a[l]),r=Math.sin(a[l]);if(i>0&&t>4){h.setColor(0);let l=n+o*t|0,i=e+r*t|0,a=t/30|0;if(a>9&&(a=9),0===a)h.fillRect(l-2,i-2,l+1,i+1);else{let t=1+(a-1)/3|0;h.fillCircle(l,i,t+1)}h.setColor(3)}let s=t+c*(1+t/90);if(s>300){f[l]=-1;continue}f[l]=s;let u=n+o*s|0,M=e+r*s|0,d=s/30|0;if(d>9&&(d=9),0===d)h.fillRect(u-1,M-1,u,M);else{let t=1+(d-1)/3|0;h.fillCircle(u,M,t)}}i++}}});